(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["fr"] = {"ui":{"lead":"On n’a pas seulement joué aux jeux : on les a peints. Agrandissez 3 300 ans de peintures et de figures pour en voir les détails.","details":"Détails","links":"Voir ou jouer au jeu","record":"À propos de l’œuvre","game":"Jeu","exhibit":"Collection","room":"Salle","room_chance":"Hasard","hint":"Pincez ou utilisez la molette pour zoomer · glissez pour déplacer · touchez un numéro","r_artist":"Artiste","r_date":"Date","r_place":"Lieu","r_medium":"Technique","r_size":"Dimensions","r_museum":"Musée","r_credit":"Provenance","r_rights":"Image","met":"The Metropolitan Museum of Art","cc0":"Accès libre (domaine public)","metlink":"L’œuvre sur le site du musée","credit":"Images : The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago et le Rijksmuseum, accès libre (domaine public).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"La reine Néfertari jouant au senet","artist":"Nina de Garis Davies (fac-similé)","date":"original v. 1290–1224 av. J.-C. · fac-similé 1921–22","place":"Égypte (Vallée des Reines)","game":"Senet","medium":"Tempera sur papier (fac-similé à mi-grandeur)","p":["Néfertari était la grande épouse royale de Ramsès II. Voici la copie d’une peinture de sa tombe, dans la Vallée des Reines, faite dans la tombe même en 1921–22 ; les fissures et les lacunes du mur ont été copiées elles aussi.","Assise devant un plateau, la reine joue au senet contre un adversaire invisible. Peint dans une tombe, le jeu signifiait sans doute plus qu’un divertissement : gagner le voyage vers l’au-delà."],"spots":[["Deux sortes de pions","Des pions pointus et des pions en forme de bobine se dressent sur le plateau : un jeu pour chaque joueur."],["La main de la reine","Ses doigts s’apprêtent à prendre un pion."],["Plateau et support","Le plateau est vu de profil : on n’en voit pas les cases. Il repose sur un support aux pieds fins."],["Son nom","Le nom de la reine est inscrit dans un ovale, un cartouche."],["L’adversaire invisible","Personne en face : la reine joue contre un adversaire qu’on ne voit pas."]]},"hydria":{"title":"Achille et Ajax jouant à un jeu de plateau (hydrie)","artist":"Attribuée au groupe de Léagros","date":"v. 510 av. J.-C.","place":"Grèce (Attique)","game":"Un jeu de dés","medium":"Terre cuite (figures noires)","p":["Pendant le siège de Troie, deux héros grecs, Achille et Ajax, tuent le temps autour d’un plateau. La scène a été inventée vers 540 av. J.-C. par le potier et peintre Exékias ; son original est conservé sur une amphore des musées du Vatican.","Le sujet a été très prisé entre 540 et 480 av. J.-C. environ : on en connaît plus de 150 exemples. Sur cette hydrie, la déesse Athéna se tient au centre. Les héros jouent à un jeu où les pions avancent selon le jet des dés."],"spots":[["Athéna","La déesse Athéna se tient entre les deux héros."],["Le héros de gauche","Sa lance toujours en main, il se penche sur le plateau."],["Le héros de droite","Lui non plus n’a pas posé ses armes : un moment de jeu en pleine guerre."],["Le plateau","Le bloc bas entre eux est le plateau."],["L’épaule","Sur l’épaule du vase, un char s’élance."]]},"liubo":{"title":"Deux figures assises jouant au liubo","date":"Ier siècle av. J.-C. – Ier siècle apr. J.-C.","place":"Chine (dynastie Han)","game":"Liubo","medium":"Terre cuite peinte","p":["Deux joueurs de liubo, le jeu à la mode de la Chine des Han. On plaçait de telles figures dans les tombes, avec le vœu que les plaisirs de la vie continuent après la mort.","Sur la photo, le plateau de liubo et les pions en os de la collection de ce musée sont posés entre eux. Les figures saisissent un moment dramatique d’une partie acharnée."],"spots":[["Le plateau de liubo","Le même plateau que « Plateau et pièces de liubo » de la collection : voyez les marques en T, L et V."],["Le joueur de gauche","Il étudie le plateau avec calme."],["Le joueur de droite","La main levée, la bouche grande ouverte : vient-il de jouer le coup gagnant ?"],["Pions sur le plateau","Des pions en os se dressent aux deux bouts du plateau."],["Pions hors du plateau","D’autres pions sont posés au sol."]]},"shahnama":{"title":"« Bozorgmehr résout le jeu indien des échecs », du Shâhnâmeh de Shâh Tahmâsp","artist":"Peinture attribuée à ʿAbd al-Vahhab","date":"v. 1530–35","place":"Iran (Tabriz)","game":"Échecs","medium":"Aquarelle opaque, encre, argent et or sur papier","p":["Une scène de l’épopée de Ferdowsi, le Shâhnâmeh (Livre des rois). Le roi de l’Inde envoie un émissaire avec un échiquier et ses pièces et défie le roi perse Nushirvan : qu’il découvre comment se joue le jeu, et l’Inde paiera tribut.","Seul le jeune sage Bozorgmehr le résout à temps. Selon le Shâhnâmeh, la Perse envoie ensuite le backgammon en retour, et les Indiens ne parviennent pas à le résoudre. Le roi et ses courtisans fixent le plateau et les joueurs."],"spots":[["L’échiquier","Les pièces se dressent sur un plateau quadrillé, si petites qu’on en distingue mal les formes."],["Le roi Nushirvan","Sur son trône, il attend de voir l’énigme résolue."],["Autour du plateau","Les joueurs se penchent sur l’échiquier."],["Les vers","Les cartouches du haut et du bas portent des vers de Ferdowsi."],["Les courtisans","Des hommes coiffés de turbans à hautes baguettes rouges regardent, debout."]]},"chaupar":{"title":"Shiva et Parvati jouant au chaupar, d’une série du Rasamanjari","artist":"Devidasa de Nurpur","date":"1694–95","place":"Inde (Basohli, Jammu)","game":"Chaupar (parent de l’ancêtre du Ludo)","medium":"Aquarelle opaque, encre, argent et or sur papier","p":["Une page d’une série illustrant le Rasamanjari, poème d’amour sanskrit du XVe siècle. Le dieu Shiva et son épouse Parvati sont assis sur une peau de tigre autour d’un plateau en forme de croix.","Shiva vient de soutirer un collier à Parvati en trichant, et elle le supplie. Couleurs hardies, profondeur incertaine de l’espace, couleur et geste porteurs de sens : ce sont les marques de l’école de Basohli."],"spots":[["Le plateau en croix","Le chaupar et le pachisi se jouent sur un plateau en forme de croix comme celui-ci."],["Barres blanches sur le plateau","Sans doute les dés longs (pasa) du chaupar."],["Shiva","Le corps blanc, un serpent autour du cou."],["Parvati","La main tendue, elle réclame son collier."],["La peau de tigre","Tous deux sont assis sur une peau de tigre."]]},"shogi":{"title":"Jeune femme et jeune homme jouant au shōgi (« Chūnagon Kanesuke », des Trente-six poètes immortels)","artist":"Suzuki Harunobu","date":"v. 1767–69","place":"Japon (Edo)","game":"Shogi","medium":"Estampe gravée sur bois (nishiki-e)","p":["Une estampe d’une série évoquant les Trente-six poètes immortels ; celle-ci figure le poète Chūnagon Kanesuke. Un soir d’été, près d’une moustiquaire, une jeune femme et un jeune homme sont penchés sur un shogiban.","Harunobu est l’artiste qui a popularisé l’estampe en couleurs, imprimée avec de nombreuses planches. Même les pièces sur le plateau sont dessinées en détail."],"spots":[["Un shogiban sur pieds","Un plateau épais sur pieds, comme ceux d’aujourd’hui."],["Une petite boîte","Sans doute la boîte des pièces."],["La moustiquaire","Une moustiquaire verte est tendue : c’est un soir d’été."],["La lanterne","Une lampe sur pied éclaire le plateau."],["Le poème","Le cartouche en forme de nuage porte le nom du poète et un poème."]]},"sugoroku":{"title":"Deux jeunes femmes jouant au sugoroku","artist":"Utagawa Toyokuni I","date":"époque d’Edo (fin du XVIIIe – début du XIXe s.)","place":"Japon (Edo)","game":"Ban-sugoroku (parent du backgammon)","medium":"Diptyque d’estampes gravées sur bois","p":["Deux estampes réunies en une large image : des jeunes femmes rassemblées dans une pièce jouent au ban-sugoroku. Ce jeu est un parent du backgammon, de la même lignée que le plateau de sugoroku du Shōsōin de cette collection.","Des pions blancs et noirs sont posés sur le plateau, et la jeune femme de droite tient un cornet pour agiter les dés. Le mont Fuji apparaît par la fenêtre."],"spots":[["Le plateau","Pions blancs et noirs sur ses longues flèches."],["Le cornet","On y agite les dés."],["Pions hors du plateau","Déjà sortis, ou pas encore entrés ?"],["Le mont Fuji","Le Fuji derrière la fenêtre."],["La jonction","Ici se rejoignent les deux estampes."]]},"eakins":{"title":"Les Joueurs d’échecs","artist":"Thomas Eakins","date":"1876","place":"États-Unis (Philadelphie)","game":"Échecs","medium":"Huile sur bois","p":["Dans le salon d’une maison de Philadelphie, deux amis jouent aux échecs sous le regard du père de l’artiste, Benjamin Eakins. Eakins tenait sa construction soignée de l’espace et la précision de ses détails de son maître parisien, Gérôme.","En 1881, Les Joueurs d’échecs devient la première œuvre acceptée par le Metropolitan Museum en don d’un artiste vivant."],"spots":[["Les pièces","Dans la pièce sombre, les pièces de l’échiquier ressortent dans la lumière."],["Le père de l’artiste","Debout, il suit la partie : Benjamin Eakins."],["Le joueur de droite","Le peintre George W. Holmes, ami du père de l’artiste."],["Le tiroir","Une inscription latine : « Le fils de Benjamin Eakins a peint ceci en 76. »"],["Au-dessus de la cheminée","Une reproduction d’un tableau de Gérôme, le maître d’Eakins."],["Le chat","Par terre, seul le chat semble se désintéresser de la partie."]]},"weiqi":{"title":"Paysage avec des immortels taoïstes jouant au weiqi","artist":"Attribué à Dai Jin","date":"Dynastie Ming, XVe–XVIe siècle","place":"Chine","game":"Weiqi (go)","medium":"Rouleau vertical ; encre et couleurs sur soie","size":"175,2 × 106,7 cm","credit":"","p":["Un grand rouleau vertical attribué au peintre Ming Dai Jin (v. 1388–1462). Originaire du Zhejiang et connu pour ses paysages vigoureux, il passa plus tard pour le fondateur de l’école Zhe. Sous des falaises vertigineuses et un grand arbre, les personnages sont minuscules.","À l’ombre, deux immortels sont assis devant un tablier de weiqi quadrillé, un plat de fruits et une jarre à côté. La silhouette accroupie à gauche évoque le bûcheron qui regarda des immortels jouer dans la montagne jusqu’à ce que le manche de sa hache pourrisse (la légende de Lanke), même si le titre du musée ne parle que d’immortels jouant au weiqi."],"spots":[["Le goban","Un tablier à rebord, finement quadrillé."],["L’immortel barbu","Un immortel à longue barbe, assis tranquillement."],["L’immortel au bonnet bleu","Penché sur le jeu ; un bol de pierres près du genou."],["La silhouette accroupie","Elle regarde depuis la gauche ; peut-être le bûcheron de la légende."],["Fruits et jarre","Un plat et une jarre au-delà du tablier."],["Signature et sceaux","Une signature et deux sceaux rouges en haut à droite."]]},"webb":{"title":"Les joueurs de backgammon (cabinet)","artist":"Philip Webb (dessin), Edward Burne-Jones (peinture), Morris, Marshall, Faulkner & Co. (fabrication)","date":"1861","place":"Grande-Bretagne (Londres)","game":"Backgammon","medium":"Pin peint, huile sur cuir, laiton, cuivre","size":"H. 185,4 ; l. 114,3 ; p. 53,3 cm","credit":"Rogers Fund, 1926","p":["L’un des tout premiers meubles de la firme que William Morris fonda avec des amis en 1861. Sur le cuir des portes, un homme et une femme vêtus à la mode médiévale jouent au backgammon, peints à l’huile. Il fut présenté à l’Exposition internationale de Londres en 1862.","Il résume l’ambition Arts and Crafts d’effacer la frontière entre beaux-arts et arts appliqués. Le fond de cuir est poinçonné de minuscules points, une technique médiévale."],"spots":[["Le plateau","Le plateau de backgammon sur la table, entre eux."],["L’homme","Un jeune homme, un pion à la main, observe le plateau."],["La femme","Face à lui, une femme tient un pion (ou un cornet à dés)."],["Les fleurs à leurs pieds","Des fleurs poussent aux pieds des joueurs."],["Le cuir poinçonné","Le fond de cuir est poinçonné de points fins qui accrochent la lumière."],["Les bandes de losanges","Des bandes de losanges sur fond d’or encadrent les portes en haut et en bas."]]},"liberale":{"title":"Les Joueurs d’échecs","artist":"Liberale da Verona","date":"vers 1475","place":"Italie (Vérone)","game":"Échecs","medium":"Tempera sur bois","size":"34,9 × 41,3 cm","credit":"Collection Maitland F. Griggs, legs de Maitland F. Griggs, 1943","p":["Fragment de la façade d’un cassone, le coffre peint qui contenait le trousseau d’une mariée dans l’Italie de la Renaissance. Liberale était aussi connu pour avoir enluminé les livres de chœur de la cathédrale de Sienne.","On y voit un moment d’une histoire d’amour non identifiée. Sur le fragment jumeau, une jeune fille à une fenêtre semble inviter un jeune homme à entrer ; ici, tous deux jouent aux échecs. Selon le musée, elle est sur le point de perdre. Les échecs étaient une image favorite de la séduction dans la littérature amoureuse de l’époque."],"spots":[["L’échiquier","Un échiquier rouge et blanc garni de pièces sombres ; la partie semble toucher à sa fin."],["Le jeune homme","Il tend la main vers l’échiquier et semble près de gagner."],["La jeune fille","Assise en face ; sur le panneau jumeau, elle l’appelle d’une fenêtre."],["La fenêtre","Derrière la fenêtre ouverte, une colline et le ciel."],["Jeunes gens qui regardent","Des hommes aux bras croisés suivent la partie."],["Jeunes femmes qui regardent","Des femmes observent la partie derrière la colonne."]]},"mirror":{"title":"Valve de miroir : couple jouant aux échecs","artist":"Anonyme","date":"1325-1350","place":"France (Paris)","game":"Échecs","medium":"Ivoire","size":"Diamètre 10,2 cm","credit":"Achat sur le fonds J. H. Wade, 1940","p":["Ce disque d’ivoire grand comme la paume couvrait un miroir de poche. Dans le Paris du XIVe siècle, un miroir de métal poli était serré entre deux plaques d’ivoire et emporté partout ; ces ivoires sculptés étaient des objets de luxe prisés de la cour et de l’aristocratie.","Sous une tente aux rideaux relevés, un jeune homme et une dame jouent aux échecs. Dans les romans médiévaux, les échecs figuraient à la fois l’amour et la guerre. On a proposé d’y voir Tristan et Iseut, ou Lancelot et Guenièvre, mais nul ne le sait. Le musée pose la question à ses visiteurs : qui, selon vous, est en train de gagner ?"],"spots":[["L’échiquier","Un échiquier sur une table à pied unique, garni de quelques pièces."],["Le jeune homme","Il tend la main pour jouer son coup."],["La dame","Une femme coiffée d’un voile ; ses doigts touchent une pièce."],["La main fermée","Son autre main, fermée, repose sur ses genoux. Tient-elle une pièce prise ?"],["La tente","Des rideaux noués de chaque côté, décor fréquent des scènes d’échecs sur les valves de miroir."]]},"morris":{"title":"Un tablier de jeu (la marelle)","artist":"Peter Flötner","date":"1500-1546","place":"Allemagne","game":"Jeu du moulin (marelle)","medium":"Gravure sur bois","credit":"Fonds de dotation Charles W. Harkness, 1923","p":["Une gravure sur bois de Peter Flötner, l’un des sculpteurs les plus doués de la Nuremberg de la Renaissance, qui dessina aussi des ornements, des meubles, des modèles d’orfèvrerie et un jeu de cartes célèbre pour sa satire. Sous les rinceaux se cache le tablier du jeu du moulin, ou marelle (« Mühle » en allemand) : trois carrés emboîtés reliés au milieu de chaque côté.","Le tablier compte 24 points. Aligner trois de ses pions (un moulin) permet d’en retirer un à l’adversaire. Ces gravures servaient aussi de modèles aux artisans, et le musée a montré cette feuille dans une exposition de modèles et de dessins d’orfèvres. On ignore si l’on jouait sur le papier ou si on le recopiait dans le bois ou le métal."],"spots":[["Le carré central","Le carré le plus intérieur, couvert d’entrelacs fins."],["Un coin extérieur","Coin du carré extérieur : l’un des 24 points où se posent les pions."],["Un coin du milieu","Les coins du carré médian sont aussi des points."],["Les lignes de jonction","Des bandes relient les trois carrés au milieu de chaque côté ; les pions s’y déplacent aussi."],["Un mascaron","Cartouches enroulés et visages en haut, en bas et sur les côtés : ornement grotesque de la Renaissance."],["La bordure de vigne","Feuilles et fruits taillés en blanc sur fond noir."]]},"leifeng":{"title":"Jeu de plateau de la pagode Leifeng","artist":"Anonyme","date":"1736-1795 (ère Qianlong)","place":"Chine","game":"Jeu de parcours","medium":"Gravure sur bois ; encre sur papier","size":"31 × 29,8 cm","credit":"Achat sur le fonds J. H. Wade, 2025","p":["Une feuille imprimée faite pour jouer, du règne de l’empereur Qianlong de la Chine des Qing. Ses cases rassemblent les personnages de la Légende du Serpent blanc : l’esprit serpent Bai Suzhen (la « Dame blanche »), sa compagne Xiaoqing (la « Petite Verte »), le jeune Xu Xuan (Xu Xian dans les versions plus tardives) et le moine Fahai, qui finit par enfermer la Dame blanche sous la pagode Leifeng, au bord du lac de l’Ouest.","Le parcours tourne en spirale depuis une case marquée 起馬, « départ », jusqu’à la pagode du centre. On courait sans doute à travers l’histoire avec des dés, comme au jeu de l’oie occidental ; les règles ne sont pas conservées. Selon le musée, ces estampes en couleurs se vendaient en ville et s’accrochaient aux murs, dans la culture visuelle urbaine — chaque couleur imprimée avec sa propre planche gravée."],"spots":[["Départ","La case marquée 起馬, « départ » : sans doute le point de départ."],["La Dame blanche et la Petite Verte","L’esprit serpent Bai Suzhen et sa compagne Xiaoqing."],["Xu Xuan","Le jeune homme qui épouse la Dame blanche."],["Le moine Fahai","Le moine qui l’enferme sous la pagode."],["La pagode Leifeng","La pagode du lac de l’Ouest à Hangzhou, où finit l’histoire."],["Le centre","Une femme assise devant la pagode et un homme agenouillé : la dernière scène du récit, et peut-être l’arrivée."]]},"tutinama":{"title":"Le singe blessé mord la main du prince, son partenaire d’échecs (d’un Tuti-nama, Contes d’un perroquet)","artist":"Dasavanta","date":"vers 1560","place":"Inde (cour moghole d’Akbar)","game":"Échecs","medium":"Tempera, encre et or sur papier","size":"20 × 14,2 cm (peinture 10,2 × 10,6 cm)","credit":"Don de Mme A. Dean Perry, 1962","p":["Une illustration du Tuti-nama, les « Contes d’un perroquet », réalisé à la cour de l’empereur moghol Akbar. C’est l’une des histoires qu’une mère perroquet raconte à ses petits pour les détourner des amitiés avec d’autres espèces, comme les renardeaux. Un singe habile aux échecs jouait souvent avec un prince.","Un jour, devant des invités, le singe fit une plaisanterie blessante ; le prince le gifla, et le singe lui mordit la main. Dehors, à droite, des serviteurs préparent le repas sous les yeux des invités stupéfaits. Une inscription en bas nomme Dasavanta, qui deviendra l’un des maîtres les plus célèbres de la cour moghole ; jeune, il posa une couche de bleu froid sous sa peinture."],"spots":[["Le singe","Il mord la main du prince, son partenaire aux échecs."],["Le prince","Le prince mordu."],["L’échiquier","Un échiquier à cases rouges posé au sol."],["Les invités stupéfaits","Les invités de la réception."],["Le repas","Dehors, des serviteurs mettent des marmites sur le feu."],["Le texte persan","En haut, l’histoire écrite en persan."]]},"teniers":{"title":"Partie de trictrac","artist":"David Teniers","date":"années 1640","place":"Flandres","game":"Backgammon","medium":"Huile sur bois, transposée sur toile","size":"59 × 80,6 cm","credit":"Don de M. et Mme Samuel D. Wise, 1943","p":["Une partie de backgammon à gros enjeu, peinte par le Flamand Teniers. Le jeu est très ancien : sa forme moderne apparaît au XVe siècle, et le nom « backgammon » naît à peu près à l’époque de ce tableau. Au XVIIe siècle, il était très en vogue et se jouait souvent pour de l’argent.","Des badauds entourent les deux joueurs, et contre le mur quelqu’un tient la marque. D’après les femmes qui regardent — l’une se penche à une fenêtre —, le musée voit ici la salle de jeu d’une maison close. Ces scènes de jeu portaient souvent une morale : le jeu d’argent était sot, voire coupable, et une perte de temps."],"spots":[["Le tablier","Un tablier de backgammon ouvert sur la table, la partie en cours."],["L’homme en blanc","Un joueur vu de dos, qui avance la main vers ses dames."],["L’homme pensif","Son adversaire, la joue dans la main."],["La marque","Un homme marque une planchette au mur : les points, ou les mises ?"],["La femme à la fenêtre","Une femme âgée qui regarde d’en haut."],["L’arrière-salle","Au fond, des hommes boivent près d’une jeune femme."]]},"imari":{"title":"Plat à deux joueurs de go","artist":"Anonyme","date":"XVIIIe siècle","place":"Japon (époque d’Edo)","game":"Go","medium":"Porcelaine moulée, émaux sur couverte (Hizen, style Imari)","size":"2,4 × 13,8 cm","credit":"Collection Severance et Greta Millikin, 1964","p":["Sur ce petit plat carré, deux hommes jouent au go sous un pin : l’un, en jaune, assis face au goban posé à même le sol ; son adversaire, en vert, adossé à l’arbre.","C’est une porcelaine d’Imari faite dans le Hizen (aujourd’hui Saga et Nagasaki), dont les verts rappellent les émaux de Kutani. Elle fut faite pour l’exportation, quand le Japon avait remplacé la Chine comme principal fournisseur de porcelaine de l’Europe."],"spots":[["Le goban","Un plateau quadrillé posé à même le sol."],["L’homme en jaune","Assis face au plateau."],["L’homme en vert","Son adversaire, adossé à l’arbre, souriant."],["Le pin","Un pin étend ses branches au-dessus d’eux."],["Le cadre rouge","Un cadre rouge à pans coupés entoure la scène."]]},"shoei":{"title":"Les Quatre Arts (l’un d’une paire de paravents)","artist":"attribué à Kanō Shōei","date":"fin du XVIe–début du XVIIe siècle","place":"Japon (époque Momoyama)","game":"Go","medium":"L’un d’une paire de paravents à six feuilles ; encre et couleurs légères sur papier","size":"153 × 358,6 cm","credit":"Fonds John L. Severance, 1979","p":["Un paravent à six feuilles attribué à Kanō Shōei, de l’école Kanō. Avec son pendant, il montre les « Quatre Arts » attendus d’un lettré chinois : jouer du qin, jouer au qi (go), la calligraphie et la peinture. Ici, des gentilshommes chinois et leurs serviteurs se délassent dans la campagne, sous les pins.","Au centre, deux hommes jouent au go tandis qu’un troisième regarde. Tout près, une table porte des livres et un qin encore dans son étui de tissu, qui attend qu’on en joue. La scène équilibre plaisir et bienséance. Le musée relève qu’un des serviteurs est distrait par le mouvement d’un poisson dans l’eau."],"spots":[["Le goban","Un plateau sur pieds ; deux gentilshommes jouent face à face."],["Les gentilshommes","Deux joueurs et un troisième qui regarde."],["La table","Sans doute la table aux livres et au qin dans son étui."],["Les serviteurs","Des serviteurs qui attendent près de la table."],["Le serviteur distrait","Allongé au bord de l’eau, il regarde un poisson."],["Le pin","Un grand pin étend ses branches au-dessus de la scène."]]},"umaya":{"title":"Paravent des écuries (go et shogi sur la véranda)","artist":"Anonyme","date":"Début du XVIe siècle","place":"Japon (époque Muromachi)","game":"Go et shogi","medium":"L’un d’une paire de paravents à six feuilles ; encre, couleurs et or sur papier","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Ce paravent de six feuilles assemblées forme une paire avec un autre. Les chevaux de prix dans leurs stalles en sont peut-être le sujet principal, mais il se passe beaucoup de choses sur la véranda, au premier plan.","On s’y affronte à deux jeux différents : le go à gauche, le shogi à droite. Selon le musée, la vivacité de la scène naît du jeu entre les chevaux agités et la stratégie tranquille des parties. Au Japon, on pensait que les singes protégeaient les chevaux, et l’on en gardait parfois dans les écuries."],"spots":[["Le goban","Un plateau finement quadrillé, avec des pierres noires."],["Deux hommes en bonnet noir","Des hommes coiffés du haut eboshi noir : celui en vert tend la main vers le plateau, celui en rouge regarde."],["Le plateau de shogi","De grandes cases, bien moins nombreuses que sur le goban."],["L’adversaire hilare","Un moine au crâne rasé saisit une pièce tandis que l’homme en face se tient la tête en riant aux éclats. Quelqu’un vient-il de marquer un point ?"],["Un singe","Au bout de la véranda, un singe en veste rouge ?"],["Un cheval","Un cheval noir se cabre, retenu par ses cordes."]]},"goryeo":{"title":"Aiguière à décor incrusté de joueurs de go","artist":"Anonyme","date":"XIIIe siècle","place":"Corée (dynastie Goryeo)","game":"Go (baduk)","medium":"Céladon à décor incrusté d’engobes blanc et noir","size":"H. 20,4 cm, diam. 14,3 cm","credit":"Don de John L. Severance, 1917","p":["Une aiguière en céladon de Goryeo, avec bec et anse. L’incrustation — graver des traits dans l’argile, les remplir d’engobe blanc et noir, puis émailler et cuire — était la spécialité des potiers de Goryeo ; ici, dans un médaillon, deux personnages assis sous un saule se détachent en blanc.","Entre eux se trouve un plateau, et le musée rapproche la scène des images de parties de go — baduk en coréen. Jouer de la cithare, du go, pratiquer la calligraphie et la peinture formaient les « quatre arts » du lettré, dont les élégantes réunions devinrent aussi des motifs d’artisans. Le céladon coréen à figures humaines est rare."],"spots":[["Le plateau","Le plateau entre les deux, un carré blanc."],["Le personnage de gauche","Assis face au plateau."],["Le personnage de droite","L’adversaire, assis en face."],["Le saule","Des branches de saule pendent au-dessus d’eux, tracées à l’engobe noir."],["Le cadre de nuages","Des volutes en forme de nuages entourent le médaillon."],["Le craquelé","De fines fissures dans la glaçure, nées au refroidissement, car argile et glaçure ne se rétractent pas autant."]]},"kangra":{"title":"Couple jouant au chaupar sur une terrasse","artist":"Anonyme","date":"v. 1790–1800","place":"Inde (Pahari, école de Kangra)","game":"Chaupar","medium":"Dessin sur esquisse à l’ocre rouge","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Un dessin d’un artiste de Kangra, dans les collines pahari au pied de l’Himalaya. La première esquisse a été faite en rouge (ocre rouge), puis reprise en noir. Sans couleur par-dessus, on suit chaque trait des personnages et des objets.","Un homme et une femme, assis sur une terrasse de part et d’autre d’un plateau en croix, jouent au chaupar, ancien jeu de course indien sur la même croix que le pachisi, où l’on avance en lançant de longs dés (pasa). Les cases ne sont pas encore tracées sur le plateau. Des servantes s’occupent du couple."],"spots":[["Le plateau en croix","Un plateau en forme de croix, posé au sol. Ses cases ne sont pas encore tracées."],["La femme","La paume tournée vers le haut : sur le point de lancer les dés ?"],["L’homme","Turban à aigrette ; il tend la main vers le plateau."],["La servante de gauche","Elle tient un petit flacon et tend une étoffe."],["La servante de droite","Elle tient un ustensile à long manche et un petit récipient."],["L’esquisse rouge","Autour du turban, l’esquisse rouge apparaît sous les traits noirs."]]},"vuillard":{"title":"La Partie de dames (de Paysages et Intérieurs)","artist":"Édouard Vuillard","date":"1899","place":"France","game":"Dames","medium":"Lithographie en couleurs (état III/III) ; imprimée par Auguste Clot, éditée par Ambroise Vollard","size":"Image 33 × 25,7 cm (feuille 38 × 30,8 cm)","credit":"Don du Hanna Fund, 1951","p":["Ambroise Vollard, marchand de tableaux impressionnistes, fut aussi un grand éditeur d’estampes. En 1895, il commanda à Pierre Bonnard un album de 12 lithographies en couleurs, puis en publia bien d’autres, dont Paysages et Intérieurs de Vuillard, imprimé par le maître imprimeur Auguste Clot.","Bonnard et Vuillard faisaient partie des nabis — « prophètes » en hébreu —, qui cherchaient un art nouveau où la forme et la couleur expriment elles-mêmes le sentiment, et qui aimaient les scènes de la vie urbaine et familiale. Dans une pièce saturée de motifs, deux hommes s’affrontent au-dessus d’un damier tandis qu’une femme, debout, regarde. La note au crayon, en bas à gauche, se lit « partie de dames »."],"spots":[["Le damier","Un petit damier, les pions en place."],["L’homme de gauche","Un homme barbu avance la main au-dessus du damier."],["L’homme de droite","Son adversaire, penché sur le jeu dans un fauteuil, à moitié caché par la femme debout."],["La femme debout","La main au menton, elle suit la partie."],["La lampe","Une lampe contre le mur. Papier peint et tissus sont couverts de motifs."],["La note au crayon","En bas à gauche, au crayon : « partie de dames »."]]},"talbot":{"title":"Les Joueurs d’échecs (photographie ancienne)","artist":"Attribuée à William Henry Fox Talbot","date":"v. 1843–47","place":"Angleterre","game":"Échecs","medium":"Épreuve sur papier salé","size":"19,9 × 15 cm","credit":"Achat grâce aux fonds de M. et Mme Everett Kovler","p":["Le procédé négatif-positif inventé par Talbot, et la reproduction illimitée qu’il permettait, a dominé la photographie jusqu’à l’ère numérique. Ses premières expériences montrent à la fois son goût de la science et ses ambitions artistiques, et les chercheurs ont confirmé qu’il a pris au moins dix vues de joueurs d’échecs.","Celle-ci n’est peut-être pas de lui : cette épreuve et d’autres de la même scène ne sont pas signées et sont sur un papier différent de celui qu’il employait. Les modèles seraient le photographe Antoine Claudet et l’assistant de Talbot, Nicolaas Henneman ; selon des recherches récentes, les images auraient été faites dans l’atelier de Claudet, puis seraient passées à Henneman, qui les aurait remises à Talbot en paiement d’une dette (notice du musée)."],"spots":[["L’échiquier","L’échiquier sur la table, les pièces alignées."],["L’homme au haut-de-forme","Le chapeau sur la tête, il saisit une pièce."],["Le songeur","La main au menton, l’adversaire étudie la partie."],["Le rideau","Un rideau tombe derrière eux : un fond pour la prise de vue ?"],["Un autre chapeau","Un second haut-de-forme est posé sur le support à droite."]]},"pvl":{"title":"Hommes jouant aux dés","artist":"Maître PVL","date":"v. 1520","place":"Pays-Bas","game":"Dés","medium":"Gravure au burin sur papier","size":"9,4 × 9,4 cm (ronde)","credit":"Collection Charles Hack et Hearn Family Trust, achat 2023","p":["L’œuvre d’un graveur anonyme actif aux Pays-Bas au début du XVIe siècle, appelé Maître PVL d’après le monogramme « PVL » gravé en bas à gauche. Sur une estampe ronde qui tiendrait dans la paume, des traits fins et serrés construisent la profondeur de la pièce et la matière des étoffes.","Deux dés sont sur la table. Un homme penché et un jeune homme au col de fourrure pointent du doigt et se disputent, peut-être sur le compte. Derrière, des femmes regardent, et une cruche de vin est posée sous la table. Les dés sont liés aux jeux d’argent depuis l’Antiquité et furent interdits à maintes reprises."],"spots":[["Les dés","Deux dés qui roulent sur la table."],["Les mains qui pointent","Deux doigts se rencontrent sur la table : une querelle sur le compte ?"],["L’homme au large chapeau","Penché en avant ; ses manches bouffantes et tailladées étaient à la mode."],["Le jeune homme au col de fourrure","Grand chapeau et col de fourrure."],["Les femmes qui regardent","Des femmes suivent la partie par-derrière."],["Le monogramme","« PVL » en bas à gauche : seul indice du nom de l’artiste."]]},"kiyohiro":{"title":"Joueuses de sugoroku","artist":"Torii Kiyohiro","date":"v. 1750","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Estampe en couleurs (benizuri-e), ōban ; éditeur Urokogataya","size":"43,5 × 29,3 cm","credit":"Collection Clarence Buckingham","p":["Torii Kiyohiro fut un artiste d’ukiyo-e actif d’environ 1737 à 1776. Voici une benizuri-e, imprimée avec peu de planches de couleur — rose beni, vert… — dans les années qui précèdent l’apparition, en 1765, des nishiki-e polychromes.","Le jeu posé sur le support noir est le ban-sugoroku : deux joueurs lancent les dés et avancent des pions blancs et noirs ; le premier à sortir tous les siens gagne. Il appartient à la même famille que le backgammon, et les estampes ukiyo-e montrent souvent des femmes qui s’y adonnent. Derrière, une femme fume une longue pipe en regardant."],"spots":[["Le plateau","Un plateau de sugoroku sur pied, avec des pions blancs et noirs."],["La figure de gauche","Elle tend la main pour déplacer un pion."],["La femme de droite","Penchée sur le plateau, l’adversaire étudie les pions."],["La femme à la pipe","Une longue pipe kiseru à la main, elle suit la partie par-derrière."],["La main levée","La femme de droite brandit un petit objet noir : le gobelet à dés ?"],["La signature","« Torii Kiyohiro hitsu », avec le sceau de l’éditeur Urokogataya."]]},"ingram":{"title":"Le Jeu d’échets chinois","artist":"John Ingram, d’après François Boucher","date":"1741–63","place":"France (Paris)","game":"Xiangqi","medium":"Eau-forte et burin","size":"Feuille 39,4 × 27,7 cm (planche 24,5 × 16,4 cm)","credit":"Collection Elisha Whittelsey, 1966","p":["Un dessin du peintre François Boucher, gravé par John Ingram, né à Londres. Installé à Paris, Ingram grava entre 1741 et 1763 une série d’estampes d’après les chinoiseries de Boucher — la Chine telle que l’imaginaient les Européens. Le titre se lit « LE JEU D'ECHETS CHINOIS ».","Une femme au chignon haut déplace une pièce sur le plateau posé sur ses genoux, sous le regard d’un petit enfant. On y voit le xiangqi, pourtant les vraies pièces de xiangqi sont toutes des disques plats, alors qu’ici de hautes pièces voisinent avec de petites pièces carrées. Le palmier et la figure assise sur l’urne relèvent moins de la Chine que du pays lointain dont rêvait l’Europe d’alors."],"spots":[["Plateau et pièces","Le plateau sur ses genoux, avec des pièces hautes et carrées. Les vraies pièces de xiangqi sont des disques plats."],["La main sur la pièce","Sa main droite déplace une pièce."],["La joue dans la main","La main gauche au menton, elle regarde le plateau."],["L’enfant qui regarde","Un enfant debout près du plateau suit la partie."],["La figure sur l’urne","Une figure assise en tailleur sur une grande urne."],["Titre et noms","« Dessiné par Fr. Boucher », « Gravé par Ingram » et le titre « LE JEU D'ECHETS CHINOIS »."]]},"posada":{"title":"Le Jeu de l’oie","artist":"José Guadalupe Posada","date":"1909","place":"Mexique","game":"Jeu de l’oie","medium":"Gravure en relief sur zinc, sur papier","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Une feuille à jouer, faite par le graveur mexicain Posada — célèbre pour ses calaveras, ses squelettes — pour l’éditeur de Mexico Antonio Vanegas Arroyo. La banderole en bas à gauche porte « JUEGO DE LA OCA » (jeu de l’oie), et le parcours s’enroule de la case 1 jusqu’à la 63, au centre.","La règle (EXPLICACION) est imprimée au milieu : un premier lancer de 5 et 4 mène au 26, de 6 et 3 au 53. Qui tombe sur une oie (un oiseau) compte encore autant ; à l’auberge (Venta, 19) on attend deux tours ; au puits (Poso, 31) et à la prison (Carcel, 52) on reste jusqu’à ce qu’un autre vienne ; le labyrinthe (42) renvoie au 39 et la mort (Muerte, 58) au départ. Il faut tomber juste sur 63. On payait aussi des mises sur certaines cases : c’était un jeu d’argent."],"spots":[["La règle","L’« EXPLICACION » du centre : l’effet de chaque case et quand payer la mise."],["La case 1","Le départ. De là, le parcours s’enroule vers le centre."],["Le puits (31)","Un puits comme une fontaine. On y reste jusqu’à l’arrivée d’un autre joueur."],["La mort (58)","La case à tête de mort : retour au départ."],["La banderole du titre","« JUEGO DE LA OCA » sur la banderole en bas à gauche, avec des enfants qui jouent dessous."],["Le nom de l’éditeur","La banderole de la déesse porte « IMPRENTA DE A. VANEGAS ARROYO », la maison qui publia beaucoup d’estampes de Posada."]]},"jintile":{"title":"Carreau à décor de femmes jouant à un jeu de plateau","artist":"Anonyme","date":"XIIIe siècle","place":"Chine (dynastie Jin)","game":"Jeu de plateau (sans doute le go)","medium":"Terre cuite (relief moulé)","size":"H. 27,3 cm, l. 24,8 cm, ép. 5,4 cm","credit":"Achat, dons des Friends of Asian Art, 2002","p":["Un carreau en relief fait sous les Jin (1115–1234), dynastie du peuple jurchen qui régna sur la Chine du Nord. Sous un arbre en fleurs, deux femmes sont assises face à face sur une estrade, un plateau entre elles.","Le plateau porte un quadrillage fin : elles jouent sans doute au go. Celle de droite se penche et montre le plateau du doigt, celle de gauche regarde. Beaucoup de tombes d’époque Jin en Chine du Nord étaient revêtues de briques sculptées de scènes de la vie quotidienne, et ce carreau ornait probablement l’une d’elles."],"spots":[["Le plateau","Un plateau finement quadrillé, sans doute un goban."],["La main qui montre","La femme de droite désigne le plateau. Son prochain coup ?"],["La femme de gauche","Les cheveux relevés, elle regarde le plateau."],["La femme de droite","Penchée vers le plateau."],["L’arbre en fleurs","Les branches d’un arbre en fleurs s’étendent au-dessus d’elles."],["L’estrade","L’estrade où elles sont assises, avec un bandeau festonné entre les pieds."]]},"kyosai":{"title":"Un pet renverse une partie de go (d’un album de croquis)","artist":"Kawanabe Kyōsai","date":"Milieu à fin du XIXe siècle","place":"Japon (époques d’Edo à Meiji)","game":"Go","medium":"Une double page d’un album en accordéon de 26 doubles feuillets ; encre et couleurs sur papier","size":"Album (fermé) 28 × 18 cm","credit":"Don d’Anne et Anthony d’Offay en l’honneur d’Evan Turner","p":["Une scène d’un album de croquis de Kawanabe Kyōsai (1831–1889), peintre actif de la fin du shogunat à l’ère Meiji, tracée à traits rapides et libres sur les pages d’un album en accordéon. Formé à la technique exigeante de l’école Kanō, Kyōsai était aussi adoré pour ses démons, caricatures et satires.","Le titre du musée dit tout : « Un pet renverse une partie de go ». À gauche, un homme coiffé d’un bonnet noir se penche ; à droite, le goban s’envole, les bols déversent une pluie de pierres et l’adversaire tombe à la renverse. Une partie sérieuse ruinée d’un seul coup : Kyōsai reprend, de son pinceau rapide, le vieil humour japonais du pet, déjà présent dans des rouleaux médiévaux."],"spots":[["L’homme au bonnet noir","Penché, le derrière en avant : la cause du désastre ?"],["Le goban qui s’envole","Le plateau quadrillé part de travers."],["Bols et pierres","Deux bols se renversent et les pierres pleuvent."],["L’éventail","Un éventail ouvert s’envole près du plateau."],["L’adversaire renversé","Sur le dos, les yeux écarquillés."],["Le trait","Des traits d’encre énergiques, comme tracés d’un jet sans esquisse."]]},"yokuts":{"title":"Plateau de jeu d’argent","artist":"Vannière yokuts (nom inconnu)","date":"v. 1900","place":"États-Unis (près de Dunlap, Californie)","game":"Huuchuish (dés en coquille de noix)","medium":"Fibres végétales (vannerie spiralée)","size":"H. 5,1 cm, diam. 61 cm","credit":"Achat grâce aux fonds de Mrs. Leonard S. Florsheim Jr.","p":["Beaucoup de peuples autochtones de Californie pratiquaient des jeux de hasard. Ce plateau servait au huuchuish, un jeu de dés réservé aux femmes : on lançait huit dés en coquille de noix sur le plateau, et l’on comptait les points avec des bâtonnets.","Le décor circulaire tissé dans le plateau montre le jeu lui-même — les dés, les bâtonnets de marque et les joueuses (notice du musée). C’est un instrument de jeu qui porte l’image de son propre jeu. Sur la photographie, des dés en coquille de noix sont posés sur le plateau et autour."],"spots":[["Les joueuses","Des figures font le tour du bord : celles qui prennent part au jeu."],["Bâtonnets de marque","Des faisceaux de petits traits verticaux : les bâtonnets pour compter."],["Motifs ronds","De petits motifs ronds : les dés, peut-être ?"],["Un dé en noix","Un dé en coquille de noix. On en lançait huit sur le plateau."],["La bande de triangles","Une bande de triangles sombres fait le tour."],["Le centre","La spirale part du centre, entourée d’un cercle en tirets."]]},"hokkei":{"title":"Ushiwakamaru bat Benkei au sugoroku","artist":"Totoya Hokkei","date":"v. 1825","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Surimono (estampe en couleurs, shikishiban)","size":"21,8 × 19,1 cm","credit":"Don d’Helen C. Gunsaulus","p":["Un surimono de Totoya Hokkei (1780–1850), élève d’Hokusai. Les surimono étaient des estampes de commande privée — souvent par des cercles de poésie, avec leurs propres vers — plus luxueuses que l’ukiyo-e du commerce, avec beau papier et pigments métalliques.","Ushiwakamaru, nom d’enfance du héros Minamoto no Yoshitsune, et le gigantesque moine-guerrier Benkei. Leur célèbre rencontre fut un duel sur le pont Gojō de Kyoto, mais ici l’affrontement devient une partie de sugoroku : l’enfant est assis, serein, derrière le plateau, et Benkei, la hallebarde au dos, se gratte la tête, vaincu. Une transposition ludique, semble-t-il."],"spots":[["Le plateau de sugoroku","Un plateau en forme de boîte, avec des pions blancs et noirs."],["Benkei se grattant la tête","En armure, le vaincu se gratte la tête."],["Ushiwakamaru","Le jeune héros, assis derrière le plateau."],["La hallebarde","La lame de la grande naginata de Benkei."],["Le poème","Des vers en haut à droite, sans doute du cercle qui commanda l’estampe."],["La signature","La signature de Hokkei dans le cartouche en bas à droite."]]},"vorsterman":{"title":"Joueurs de trictrac (scène nocturne)","artist":"Lucas Emil Vorsterman, d’après Adam de Coster","date":"v. 1630","place":"Flandre (Anvers)","game":"Backgammon","medium":"Gravure au burin sur papier ivoire","size":"Image 25,5 × 34,4 cm","credit":"Collection Bernard F. Rogers","p":["Adam de Coster était, vers 1630 à Anvers, un peintre réputé de scènes nocturnes à la chandelle, au moment où Vorsterman, dans la même ville, gravait les œuvres de contemporains en vogue. Élève de Rubens, Vorsterman se brouilla avec son maître et partit en Angleterre ; il fit ensuite des gravures plus contrastées, plus stylisées, caravagesques, comme celle-ci.","Autour d’une table dans une pièce sombre, des hommes se penchent sur un plateau de trictrac. À la manière de De Coster, deux flammes de chandelle éclairent les visages autour de la table (notice du musée). À droite, un jeune joueur de luth nous regarde."],"spots":[["Le plateau","Un trictrac ouvert comme une boîte sur la table."],["La chandelle","Une chandelle sur son bougeoir ; sa flamme éclaire les visages."],["L’homme à la pipe","Coiffé d’un large chapeau, il fume en regardant la partie."],["L’homme de dos","Penché, les mains sur la table."],["Le joueur de luth","Un jeune homme au luth qui nous sourit."],["Les noms","« A. De Coster pi. » en bas à gauche, « Vorsterman » en bas à droite."]]},"zorn":{"title":"Joueurs d’échecs","artist":"Anders Zorn","date":"1891","place":"Suède","game":"Échecs","medium":"Eau-forte sur papier vergé ivoire","size":"Image 13,5 × 9,6 cm (cuivre 13,9 × 10 cm)","credit":"Collections d’eaux-fortes d’Anders Zorn de Wallace L. DeWolf et Charles Deering","p":["Une eau-forte de l’artiste suédois Anders Zorn (1860–1920), célèbre dans le monde pour ses portraits à l’huile et à l’aquarelle, qui laissa aussi un important œuvre gravé. Le cuivre n’est pas plus grand qu’une main.","Il suffit de traits rapides et obliques superposés pour faire surgir du cuivre une pièce sombre et deux personnes. L’homme au premier plan, de dos, se penche sur l’échiquier ; en face, l’autre baisse les yeux et réfléchit au coup suivant. Les pièces sont dessinées d’un trait fin. On ne sait pas qui a posé."],"spots":[["L’échiquier et les pièces","La zone claire en bas est l’échiquier ; les petits traits verticaux sont les pièces."],["L’homme au premier plan","De dos, penché sur l’échiquier."],["L’adversaire","Tête baissée, les yeux sur l’échiquier."],["Le fond sombre","Le fond de la pièce, fait de lignes verticales."],["Les traits obliques","Le manteau est fait de traits diagonaux rapides superposés."],["La signature","Signé « Zorn » au crayon sous le cuivre."]]},"harunobu-sugoroku":{"title":"Regarder la partie (sugoroku)","artist":"Suzuki Harunobu","date":"v. 1766","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Estampe en couleurs (chūban, surimono)","size":"28,5 × 21 cm","credit":"Collection Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) fut la figure centrale de la naissance, vers 1765, des nishiki-e, estampes polychromes imprimées avec de nombreuses planches. Celle-ci est un surimono d’édition privée, dont les couleurs douces et superposées montrent la nouveauté.","Dans une pièce aux pruniers en fleurs, deux jeunes filles jouent sur un plateau de sugoroku en forme de boîte, tandis qu’une troisième, debout, regarde. Des pions blancs et noirs couvrent le plateau ; celle de gauche en déplace un, celle de droite tend la main. La porte coulissante du fond est peinte d’une cascade et de pins."],"spots":[["Le plateau de sugoroku","Un plateau de ban-sugoroku en forme de boîte, aux pions blancs et noirs."],["La jeune fille de gauche","En kimono à grues de papier, elle déplace un pion."],["La jeune fille de droite","Penchée, elle tend la main vers le plateau."],["La spectatrice","Debout, elle regarde la partie, un objet à long manche à la main."],["Le prunier","Un prunier blanc étend ses branches depuis le haut."],["La porte peinte","Une porte coulissante peinte d’une cascade et de pins."]]},"kota":{"title":"Le maharao Kishor Singh II de Kota adorant Krishna sous la forme de Brij Rajji","artist":"Anonyme","date":"v. 1825","place":"Inde (Rajasthan, Kota)","game":"Pachisi","medium":"Tempera à la gomme, argent et or sur papier","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Le souverain du petit État princier de Kota (r. 1819–28), vêtu en prêtre de la secte Pushti Marg, présente une lampe à cinq flammes. Dans le petit sanctuaire de l’autel se dressent des images en métal de Krishna entouré de deux épouses — une idole vénérée seulement à Kota.","Une multitude de lampes de verre pend du plafond, et sur les marches menant à l’autel sont disposés des jouets et des jeux pour amuser Krishna et ses compagnons : éléphants de laiton, vaches d’argent, balles et un plateau de pachisi (notice du musée). Le tissu rouge en croix est ce plateau : le pachisi offert comme jouet au dieu."],"spots":[["Le plateau de pachisi","Le tissu rouge en croix sur les marches : un plateau de pachisi."],["Éléphants","Deux éléphants de laiton près du plateau."],["Balles","Des balles dorées sur la marche supérieure."],["Krishna","Les images de Krishna et de deux épouses dans le sanctuaire."],["Le souverain et sa lampe","Vêtu en prêtre, il présente une lampe à cinq flammes."],["Lampes de verre","Une foule de lampes de verre pend du plafond."]]},"coyote":{"title":"Le Jeu du coyote","artist":"Suiveur de José Guadalupe Posada","date":"Non daté","place":"Mexique","game":"Coyote et poules (famille du renard et des oies)","medium":"Gravure en relief sur zinc, sur papier","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Une feuille à jouer, imprimée en relief sur zinc comme celles que Posada faisait pour les presses populaires de Mexico. En haut, « JUEGO DEL COYOTE » (jeu du coyote) ; tout autour, des coyotes attaquent le poulailler et un homme brandit un bâton pour en chasser un. La bande du bas indique « Propriété d’Ildefonso T. Orellana ».","La règle est imprimée dans l’« EXPLICACION » en bas : deux joueurs, l’un avec quinze poules, l’autre avec un seul coyote. Les poules avancent ou vont de côté mais ne reculent jamais ; le coyote se déplace en tous sens et mange une poule en sautant par-dessus si la place derrière est libre. Les poules gagnent en enfermant le coyote. C’est le même jeu de chasse que le renard et les oies européen."],"spots":[["La place du coyote","La tête de coyote dans le cercle central : le coyote part de là."],["Les places des poules","Les cercles aux poules : on y pose leurs pions."],["La règle","L’« EXPLICACION » : pions, déplacements et victoire."],["Le titre","« JUEGO DEL COYOTE » — jeu du coyote."],["Un coyote sur une poule","En bas à gauche, un coyote s’en prend à une poule."],["L’homme au bâton","En haut à droite, un homme lève un bâton contre un coyote."]]},"mons":{"title":"Trictrac pour Mons (Bergen), 1709","artist":"Pieter Nolpe (planche et éditeur)","date":"Planche 1623–53 ; tirage v. 1709","place":"Pays-Bas (Amsterdam)","game":"Trictrac (de la famille du backgammon)","medium":"Eau-forte, burin et vers typographiés","size":"Feuille 35,8 × 18,6 cm (cuivre 12,9 × 17,5 cm)","credit":"","p":["Quatre hommes jouent au trictrac autour d’une table. Selon la notice du musée, les lettres A–D désignent le duc de Marlborough, l’électeur de Bavière, le seigneur d’Ouwerkerk et le duc de Villeroy. C’est une satire du siège et de la prise de Mons (Bergen en néerlandais) aux Français par les Alliés en 1709, présentée comme une partie dont l’enjeu est la ville. Dans la pièce du fond (E), le roi Philippe V d’Espagne est avec une femme.","Le cuivre est signé de Pieter Nolpe comme graveur et éditeur, mais Nolpe est mort au début des années 1650 : on a sans doute retiré une vieille planche du XVIIe siècle en y ajoutant des lettres et un nouveau poème. Celui-ci commence en disant que le jeu des grands seigneurs n’est que tiktak et verkeer (deux jeux de tables), puis raille chaque joueur."],"spots":[["Le plateau","Le trictrac sur la table : la ville est l’enjeu."],["A, Marlborough","Debout, il regarde le plateau : le général anglais des Alliés."],["B, l’électeur de Bavière","Tête nue, affalé sur sa chaise."],["C, Ouwerkerk","Au chapeau à plumes : le général hollandais."],["E, la pièce du fond","Au fond, Philippe V avec une femme dans la chambre."],["Le poème","Vers néerlandais imprimés dessous, raillant les joueurs A à E."]]},"stembus":{"title":"L’Urne : un jeu de l’oie politique","artist":"Johan Michaël Schmidt Crans (graveur)","date":"1867","place":"Pays-Bas","game":"Jeu de l’oie (satire)","medium":"Lithographie","size":"66 × 50 cm","credit":"","p":["Une estampe satirique en forme de jeu de l’oie, parue avec l’hebdomadaire De Nederlandsche Spectator, n° 9, du 2 mars 1867, accompagnée d’une feuille volante de règles (notice du musée). Les cases portent les portraits des ministres de l’époque.","On part du Binnenhof, le parlement de La Haye, et l’on arrive au centre, case 64, « Insulinde » — nom poétique des Indes néerlandaises —, où un portrait peint du ministre Pieter Mijer pend à l’île de Java. Mijer était passé de ministre des Colonies à gouverneur général des Indes, et cette nomination avait déclenché une tempête politique. La case de plus, une au-delà des 63 habituelles, est sans doute là pour la chute."],"spots":[["Le départ","Le bâtiment en haut à gauche : on part du Binnenhof de La Haye."],["Le portrait de Mijer","Case 63 : un portrait encadré de Pieter Mijer, suspendu à l’île par des cordes."],["Insulinde 64","L’île et le nombre 64 au centre : l’arrivée."],["L’urne","« DE STEMBUS » (l’urne) en bas à droite : la boîte du titre."],["Les ministres","Les visages des ministres du moment apparaissent dans les cases."],["Le coq","Un coq dans une case ; on ignore de quoi il se moque."]]},"koorai":{"title":"Coréens autour d’un jeu de plateau (d’après le Nippon de Siebold)","artist":"James Erxleben (lithographe), d’après un dessin de « Toioske »","date":"1832–52","place":"Pays-Bas (Leyde) / Coréens","game":"Jeu de plateau (sans doute le go)","medium":"Lithographie teintée, coloriée à la main","size":"Feuille 38 × 55,5 cm","credit":"Don de F. G. Waller","p":["Une planche de NIPPON, la grande œuvre que le médecin d’origine allemande Philipp Franz von Siebold publia à Leyde d’après ce qu’il avait vu au comptoir néerlandais de Nagasaki (1823–30). Elle porte « TAB. I » en haut à droite et « KOORAI » (Corée) en bas, avec « une famille de pêcheurs » en néerlandais et en allemand. Erxleben l’a dessinée sur pierre ; la planche nomme le dessinateur « Toioske ».","Quatre hommes assis par terre entourent un plateau ; à gauche une femme tient un petit enfant par la main, à droite un homme debout tient un long bâton et une bourse. Devant, un chapeau noir à large bord (gat) est posé au sol. Le plateau montre un quadrillage et des pierres rondes : sans doute du go (baduk en coréen), bien que la notice dise seulement « un jeu de plateau »."],"spots":[["Le plateau","Quadrillage et pierres rondes : sans doute une partie de go."],["Le chapeau noir","Un chapeau noir à large bord (gat) au sol."],["Mère et enfant","Une femme tenant un enfant regarde la partie."],["L’homme debout","Debout, avec un long bâton et une bourse."],["L’homme penché","En veste bleue, il scrute le plateau."],["Le titre","« KOORAI » (Corée), avec « une famille de pêcheurs » en néerlandais et en allemand."]]},"cairo":{"title":"Groupe autour d’un jeu de plateau devant un café (Le Caire)","artist":"Délié & Béchard (Hippolyte Délié et Émile Béchard)","date":"v. 1869–90","place":"Égypte (Le Caire)","game":"Jeu de plateau (sans doute les échecs)","medium":"Tirage sur papier albuminé","size":"10,8 × 16,4 cm","credit":"","p":["Une photographie d’Hippolyte Délié et Émile Béchard, photographes français installés au Caire. Le carton porte le nom de l’atelier, « Au Jardin de l’Esbékieh », et « Caire (Égypte) ». Les voyageurs achetaient ce genre d’images en souvenir de l’Égypte.","Des hommes assis par terre devant une boutique à fenêtre grillagée entourent un plateau posé sur un support bas. De hautes pièces s’y dressent : sans doute des échecs (chatrandj en arabe), bien que la notice du musée dise seulement « un jeu de plateau ». Chacun reste immobile pour la longue pose."],"spots":[["Plateau et pièces","Le plateau sur un support bas, aux hautes pièces : sans doute les échecs."],["La fenêtre grillagée","Une fenêtre à treillis de bois, typique des vieilles maisons du Caire."],["L’homme au bâton","Assis avec un bâton, il suit la partie."],["Le panier","Un panier tressé posé au sol."],["L’enfant qui regarde","Un enfant regarde le plateau par-derrière."],["Le nom de l’atelier","« AU JARDIN DE L’ESBÉKIEH » et « CAIRE (EGYPTE) » sur le carton."]]},"vanmour":{"title":"Compagnie d’Arméniens jouant aux cartes","artist":"Jean-Baptiste Vanmour","date":"v. 1720–37","place":"Empire ottoman (Istanbul)","game":"Cartes","medium":"Huile sur toile","size":"44,5 × 58,5 cm","credit":"","p":["Né en Flandre, Vanmour gagna Istanbul en 1699 avec l’ambassadeur de France et vécut dans la ville jusqu’à sa mort, peignant les cérémonies de la cour et la vie de ses habitants. Le musée précise que les vêtements des hommes les désignent comme Arméniens.","À la lueur d’une grande chandelle, hommes et femmes jouent aux cartes autour d’une table couverte d’un tapis rouge. Des cartes sont distribuées sur la table, et certains scrutent leur jeu. Dans le coin gauche, une vieille femme file. La notice ne dit pas de quel jeu il s’agit."],"spots":[["Cartes sur la table","Des cartes sur la table au tapis rouge."],["La grande chandelle","Une seule chandelle éclaire toute la compagnie."],["La vieille fileuse","Une vieille femme file dans le coin gauche."],["Femme regardant son jeu","À l’extrême droite, une femme examine ses cartes."],["L’homme en fourrure","Un homme au manteau bordé de fourrure ; l’habit désigne des Arméniens."],["Penché sur la table","Un personnage se penche sur la table, cartes en main."]]},"algiers":{"title":"Trois hommes jouant à un jeu de plateau (Alger)","artist":"Anonyme","date":"1851–1900","place":"Algérie (Alger)","game":"Jeu de plateau (sans doute le trictrac)","medium":"Tirage sur papier albuminé","size":"14,0 × 10,0 cm","credit":"","p":["Une photographie anonyme portant, écrit à la main sous l’image, « Alger ». Avec des chaises et une petite table devant un fond uni, elle a sans doute été prise en atelier. Voyageurs et collectionneurs achetaient de telles images de gens d’Afrique du Nord.","Deux hommes se font face devant un plateau à rebord ; celui de droite tend la main vers une pièce. Des pions ronds sont empilés sur le plateau : sans doute le trictrac ou backgammon (appelé tawla dans la région, entre autres), même si la notice dit seulement « un jeu de plateau ». Sur la petite table devant, le service à café."],"spots":[["Plateau et pions","Un plateau à rebord où s’empilent des pions ronds."],["Le spectateur debout","Un homme à la ceinture d’étoffe regarde la partie, debout derrière."],["Le vieil homme, à gauche","Un homme âgé, la tête enturbannée, pensif."],["L’homme de droite","Un linge blanc sur la tête, il se penche sur le plateau."],["Le service à café","Plateau et petites tasses sur une table ajourée."],["La main qui joue","La main du joueur de droite, prête à prendre un pion."]]},"circo":{"title":"Jeu du cirque (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Non daté","place":"Mexique","game":"Jeu d’argent à deux dés","medium":"Gravure en relief ou similigravure sur papier vélin chamois","size":"26,2 × 35,0 cm","credit":"","p":["Une feuille de jeu attribuée, avec un point d’interrogation, au graveur mexicain Manuel Manilla. En bas à droite figure son vendeur, l’imagerie « El Teatro », avec son adresse. Ces feuilles bon marché se vendaient dans la rue et servaient sans doute de plateau telles quelles.","Au centre, un chapiteau de cirque, entouré d’écuyers acrobates, d’une pyramide humaine, d’un hercule et d’autres, chacun marqué d’un nombre de 2 à 12. L’« Esplicacion » en haut à gauche dit que tous, enfants compris, peuvent jouer : on lance deux dés et l’on mise sur la case obtenue, ou l’on prend la mise qui s’y trouve. Qui fait douze rafle tout."],"spots":[["Le chapiteau","Le titre « JUEGO DEL CIRCO » et le chapiteau, case 12."],["La règle","La règle, sous le titre « ESPLICACION »."],["L’écuyère","Une danseuse sur un cheval au galop : case 6."],["La tour humaine","Un homme debout sur les épaules d’un autre : case 4."],["L’hercule","Un homme soulevant un poids en forme de canon : case 8."],["Le nom de l’imagerie","« De venta, Estampería “El Teatro” » et l’adresse."]]},"loteria":{"title":"Jeu de lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"Mexique","game":"Lotería (jeu d’images annoncées)","medium":"Gravure en relief ou similigravure sur papier vélin chamois","size":"30,0 × 40,0 cm","credit":"","p":["Le graveur mexicain Posada dessina d’innombrables images pour l’éditeur de Mexico Antonio Vanegas Arroyo, dont les feuilles bon marché diffusaient nouvelles, chansons et jeux. Celle-ci porte le titre « JUEGO DE LOTERIA » et le nom de Vanegas Arroyo.","Trente-huit petites images légendées couvrent la feuille : l’étoile, la lune, le scorpion, le diable, la tête de mort, le coq, l’imprimerie, etc. À la lotería, proche du loto ou du bingo, un meneur tire des cartes et annonce les images, que les joueurs marquent sur leur planche avec des haricots ou autre chose. La feuille était sans doute découpée en cartes."],"spots":[["Titre et éditeur","« JUEGO DE LOTERIA » et le nom de la maison Vanegas Arroyo."],["L’étoile","« ESTRELLA », première image en haut à gauche."],["La lune","« LUNA », un croissant à visage."],["La Mort","« MUERTE » : un squelette à la faux jouant du pipeau."],["Le tlachiquero","« TLACHIQUERO » : un homme qui recueille la sève de l’agave."],["L’imprimerie","« IMPRENTA » : des ouvriers à la presse, là où se faisaient ces feuilles."]]},"jeupol":{"title":"« Jeu polonais », ou damier","artist":"Anonyme","date":"1833–1900","place":"Belgique ou Pays-Bas","game":"Dames (damier de 10 × 10)","medium":"Gravure sur bois et texte typographié","size":"32,2 × 39,6 cm","credit":"","p":["Une feuille volante titrée en français et en néerlandais, « JEU POLONAIS OF DAMSPEL ». Le « jeu polonais » désignait en France les dames sur damier de 10 × 10. En haut à droite figure le numéro d’éditeur, « n. 106 ».","Comme l’indique la notice du musée, on compte 100 cases, 50 blanches et 50 noires, avec des bordures ornementales à gauche et à droite. Aucun pion n’est imprimé : c’était sans doute un damier bon marché utilisé tel quel, avec des haricots ou des boutons. Le papier garde ses plis."],"spots":[["Le titre","Les mots « JEU POLONAIS OF DAMSPEL »."],["Le numéro","Le numéro d’éditeur « n. 106 »."],["La bordure gauche","Une colonne de rosaces."],["La bordure droite","Le même motif de l’autre côté."],["Les cent cases","Le damier de 10 × 10 ; les cases foncées sont hachurées."],["Le pli","Un pli resté dans le papier ; peut-être le portait-on plié."]]},"dkaart":{"title":"Jeu de domino et de cartes à découper","artist":"Anonyme (Brepols)","date":"1800–1833","place":"Belgique (Turnhout)","game":"Dominos et cartes","medium":"Gravure sur bois coloriée en bleu, rouge et jaune ; texte typographié","size":"34,3 × 41,9 cm","credit":"","p":["Selon la notice du musée, la feuille porte 32 cartes à jouer et 28 dominos à découper. C’est le numéro 114 du catalogue de l’éditeur Brepols, avec en pied le revendeur « D. Pouwels, Bergen-op-Zoom ». Le titre est en néerlandais et en français.","À gauche, les 28 dominos, du double blanc au double six, forment un triangle. À droite, 32 cartes, du sept au dix plus les figures et les as de chaque couleur : un jeu pour le piquet et autres. Comme personne ne l’a découpée, on la voit telle qu’elle sortit de presse."],"spots":[["Le titre","Les mots « DOMINO EN KAARTSPEL »."],["Double blanc","Le sommet du triangle : le domino sans points."],["Double six","La plus forte pièce, au bout de la dernière rangée."],["As de pique","La deuxième carte de la colonne de gauche."],["Une figure","Un roi colorié de rouge, bleu et jaune."],["Le revendeur","« D. POUWELS, Bergen-op-Zoom » en bas."]]},"apen":{"title":"Deux singes jouant au trictrac","artist":"Quirin Boel, d’après David Teniers","date":"1635–1690","place":"Flandres","game":"Trictrac","medium":"Eau-forte","size":"11,0 × 14,5 cm","credit":"","p":["Planche d’une suite, un titre et six planches, où des singes miment les occupations humaines. En bas à gauche : « D. Teniers inventa et publia, avec privilège » ; Quirin Boel a gravé le dessin du peintre flamand Teniers.","Comme le décrit la notice du musée, deux singes assis par terre ont un trictrac entre eux. Celui de gauche boit du vin dans un verre ; celui de droite, coiffé d’un chapeau à plume de coq, tend la main vers une dame. Sans doute une moquerie des hommes livrés au vin et au jeu."],"spots":[["Le trictrac","Un tablier pliant posé au sol, avec ses flèches et ses dames."],["Le singe de gauche","Un singe en veste, assis devant le jeu."],["Le verre","Le verre levé par le singe de gauche."],["Le chapeau à plume","Une plume de coq au chapeau du singe de droite."],["La cruche","Une cruche aux pieds du singe de gauche."],["L’inscription","« D Teniers in et excud cum privilegio »."]]},"dstereo":{"title":"Hommes jouant aux dominos à une table (stéréographie)","artist":"Anonyme","date":"1850–1880","place":"Inconnu (inscription en néerlandais)","game":"Dominos","medium":"Tirage sur papier albuminé (vue stéréoscopique)","size":"8,5 × 17,0 cm","credit":"","p":["Une vue stéréoscopique : deux photographies presque identiques côte à côte. Regardées dans un stéréoscope, elles se fondent en une scène en relief. Au bord gauche, on lit à la main « Het dominospel » (le jeu de dominos).","Une table a été sortie au soleil devant un bâtiment, et des hommes en bras de chemise tiennent leurs dominos. Deux regardent la partie debout ; celui de droite porte un bonnet blanc. Comme chacun devait rester immobile, la scène a sans doute été arrangée pour l’appareil."],"spots":[["Les dominos","Des dominos tenus face cachée."],["L’homme au bonnet blanc","Assis à droite, ses dominos en main."],["L’homme au foulard","Debout, il regarde la partie."],["L’homme de gauche","Un jeune homme accoudé, penché sur son jeu."],["L’inscription","« Het dominospel. » écrit au bord gauche."],["La seconde image","La vue de droite, prise d’un point un peu décalé : ensemble, elles donnent le relief."]]},"gojo":{"title":"Deux femmes jouant au go","artist":"Anonyme","date":"1870–1891","place":"Japon","game":"Sans doute le go","medium":"Tirage albuminé colorié à la main","size":"9,0 × 13,5 cm","credit":"","p":["Une photographie en noir et blanc coloriée au pinceau. De telles images se faisaient dans les ateliers de Yokohama et d’ailleurs, en souvenirs pour les étrangers. Celle-ci était collée dans un album de photos d’un voyage à Manille.","Devant un décor d’alcôve et un paravent, deux femmes sont assises de part et d’autre d’un plateau à pieds ; celle de gauche pose une pierre. Des pierres blanches et noires sont sur le plateau : sans doute le go, même si la notice du musée dit « un jeu de plateau ». Sur le plateau de service devant, des douceurs et des bols."],"spots":[["Le goban et les pierres","Un épais plateau à pieds, avec pierres blanches et noires."],["La main qui joue","La femme de gauche pose une pierre."],["La femme de gauche","Elle se tourne vers nous ; son obi forme un grand nœud."],["La femme de droite","En kimono rayé, la main près du plateau."],["Plateau et bols","Douceurs et tasses devant elles."],["Les fleurs","Un vase de fleurs sur un support, derrière."]]},"meade":{"title":"Deux hommes jouant aux échecs","artist":"Charles Richard Meade et Henry William Mathew Meade","date":"1852","place":"États-Unis","game":"Échecs","medium":"Daguerréotype","size":"6,9 × 8,3 cm","credit":"","p":["Un daguerréotype de l’atelier des frères Meade, photographes nés en Angleterre et installés en Amérique. Le daguerréotype forme l’image directement sur une plaque de cuivre argentée : chacun est unique et ne peut être retiré. Celui-ci est logé dans un petit étui de cuir, derrière un passe-partout doré.","Deux jeunes gens font face à un échiquier posé sur un guéridon ; celui de gauche a les doigts sur une pièce. Celui de droite, la main sur la poitrine, étudie la position. Comme il fallait rester longtemps immobile, le coup est sans doute posé."],"spots":[["L’échiquier","L’échiquier et les pièces blanches, sur un guéridon tendu de tissu fleuri."],["L’homme de gauche","Les doigts sur une pièce."],["L’homme de droite","Il regarde l’échiquier."],["La main sur la poitrine","La main pensive du joueur de droite."],["Le tissu","Un petit guéridon couvert d’étoffe fleurie."],["Le passe-partout doré","Le cadre doré et l’étui qui protègent la plaque."]]},"reise":{"title":"Le voyage autour du monde, par eau et par terre","artist":"Anonyme","date":"XIXe siècle","place":"Sans doute pays de langue allemande","game":"Jeu de parcours à un dé, avec mises","medium":"Lithographie","size":"42,5 × 33,7 cm","credit":"","p":["Une feuille de jeu titrée en allemand « Le voyage autour du monde, par eau et par terre : un nouveau et divertissant jeu de dés ». Un plateau rond porte les cases 1 à 41, illustrées d’un ballon, de voiliers, d’un vapeur, d’une locomotive, de gens de diverses nations, etc. Numéro « No. 107 » en bas à droite.","En dessous, la règle en allemand, anglais, néerlandais et français. Chacun verse d’abord 15 marks à la « caisse du voyage » commune, puis lance un dé à son tour et avance son pion. Tomber sur une grande image rapporte 2 marks, un numéro sans image coûte 2 marks d’amende, et qui atteint le 41 rafle le reste."],"spots":[["41 : la diligence","Le but au centre : une diligence avec voyageurs et cocher."],["1 : l’Anglais","La case de départ, « Engländer » en haut-de-forme."],["Le ballon","Une case avec un ballon dans le ciel."],["Le voilier","Un navire toutes voiles dehors."],["La locomotive","Une locomotive à vapeur fumante."],["La règle","La règle, imprimée en quatre langues."]]},"huchten":{"title":"Les dés pour la vie ou la mort","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Pays-Bas","game":"Dés","medium":"Huile sur toile","size":"67,5 × 76,0 cm","credit":"","p":["Œuvre du peintre hollandais Jan van Huchtenburg (1647–1733), connu pour ses batailles, signée en bas à gauche. Le titre du musée est « Le jeu de dés pour la vie ». Hors d’une forteresse, deux prisonniers jettent les dés sur un tambour, entourés d’officiers et de soldats.","Au fond à droite se dresse un gibet, et des soldats regardent depuis le rempart à gauche. Il s’agit sans doute de soldats condamnés tirant au sort aux dés celui qui sera exécuté. Un prisonnier montre le tambour ; l’autre, à genoux, regarde le coup."],"spots":[["Tambour et dés","Un tambour sert de table pour jeter les dés."],["Le prisonnier qui montre","Debout, il désigne le tambour."],["Le prisonnier à genoux","En chemise blanche, penché sur le tambour."],["L’officier à cheval","Coiffé d’un chapeau, il regarde du haut de sa monture."],["Le gibet","Le gibet, en haut à droite."],["Soldats sur le rempart","Des soldats qui regardent du haut du mur."]]},"vertu":{"title":"Le jeu de la vertu (Spel der Deugd)","artist":"Jan Gerritsz. Visser (d’après J. Voorman)","date":"1798","place":"Pays-Bas","game":"Jeu d’argent à deux dés","medium":"Gravure au burin, eau-forte et typographie","size":"56,9 × 38,0 cm","credit":"","p":["Une grande feuille de jeu titrée en néerlandais et en français « Le jeu de la vertu ». Dans un temple à colonnes trône la Vertu, avec la Prospérité à gauche et la Pauvreté à droite. Des médaillons de vertus — Sincérité, Gratitude, Amour… — ornent les colonnes, et les socles montrent des vices comme l’Avarice, l’Orgueil et la Paresse.","Selon la règle du bas, on joue avec deux dés ou en tirant des billets. Aux dés, les joueurs misent 63 en tout puis jettent à tour de rôle dans le sens du soleil. Chaque coup désigne une vertu ou un vice : le double six, la Vertu, prend la cagnotte, et le double as, le Vice, paie huit. Sous chaque image, « T » indique ce qu’on tire et « B » ce qu’on paie."],"spots":[["Le titre","« SPEL DER DEUGD » au fronton."],["La Vertu","La Vertu trônant au centre ; le double six prend tout."],["La Prospérité","La Prospérité et sa corne d’abondance."],["Le Vice","Le double as, le Vice : un enfant levant une coupe."],["L’Avarice","L’Avarice sur le socle ; « B » et les dés disent ce qu’on paie."],["La règle","La règle, imprimée serrée en bas."]]},"charros":{"title":"Les charros contrebandiers : jeu de dés","artist":"José Guadalupe Posada","date":"Non daté","place":"Mexique","game":"Jeu de parcours à trois dés","medium":"Lithographie","size":"29,9 × 40,4 cm","credit":"","p":["Un jeu de parcours illustré par Posada, intitulé « LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS » (Les charros contrebandiers / Jeu de dés). En bas, la mention de l’imprimerie A. Vanegas Arroyo, Mexico ; Posada a signé en bas à droite. Les charros, cavaliers mexicains, galopent en sombrero dans les coins.","Des cases rondes bordées de corde serpentent sur tout le plateau, peuplées d’animaux, de personnages, d’un train, etc. L’« Explication » en haut à droite dit qu’on joue avec trois dés. Trois as au premier coup gagnent ; tomber sur la tête de mort perd ; le cerf fait toucher la cagnotte, les voleurs font payer, et le lion immobilise jusqu’à ce qu’un autre vienne."],"spots":[["Le titre","« LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS »."],["L’explication","La règle, sous « EXPLICACION »."],["Les joueurs","Des gens autour d’une table, jouant sur un plateau, en bas à gauche."],["Les dés","Trois dés dessinés au milieu du plateau."],["Le charro à cheval","Un charro au galop qui fait tournoyer son lasso."],["L’imprimeur","« IMPRENTA DE A. VANEGAS ARROYO, MÉXICO »."]]},"snuffwq":{"title":"Tabatière à décor de joueurs de weiqi","artist":"Chine","date":"Dynastie Qing, marque et époque Daoguang (1820–50)","place":"Chine","game":"Weiqi (go)","medium":"Porcelaine à décor d’émaux sur couverte","size":"Haut. 5,7 cm","credit":"","p":["Un petit flacon où l’on portait le tabac à priser dans la Chine des Qing. Selon la notice du musée, il porte une marque du règne Daoguang et date de 1820–50. Sur sa panse de porcelaine blanche, haute d’environ six centimètres, un paysage de montagne et des personnages sont peints aux émaux.","Près d’un rocher en grotte, deux vieillards sont assis devant un goban posé sur un support bleu ; celui de gauche va poser une pierre. Derrière lui, un enfant tenant un bâton regarde. Le sujet évoque sans doute le bûcheron qui regarda jouer les immortels."],"spots":[["Le goban","Un tablier sur support bleu, finement quadrillé."],["Le vieillard barbu","En robe violette, il tend la main vers le jeu."],["Le vieillard d’en face","Assis à droite, la main levée."],["L’enfant au bâton","Il regarde par-derrière."],["La grotte","Un rocher en forme de grotte."],["Le bouchon","Un bouchon vert."]]},"ostade":{"title":"Joueurs de trictrac dans une auberge","artist":"Adriaen van Ostade","date":"1653","place":"Pays-Bas (Haarlem)","game":"Trictrac","medium":"Eau-forte","size":"8,5 × 7,4 cm","credit":"","p":["Une eau-forte grande comme la paume, du peintre de Haarlem Ostade, connu pour ses scènes paysannes, signée « A. ostade » en bas. Dans une auberge sombre, la lumière d’une fenêtre à plombs éclaire les personnages.","À la table de gauche, deux hommes s’affrontent au trictrac tandis qu’un troisième regarde par-derrière. À droite, un homme adossé au mur tient un gobelet. Une grosse cruche gît au sol ; on dirait un après-midi paresseux à l’auberge."],"spots":[["Le tablier","Un trictrac posé sur la table."],["Le joueur de gauche","Un homme coiffé d’un chapeau face au jeu."],["Le joueur de droite","Penché sur le jeu."],["Le curieux","Un homme debout derrière, qui regarde."],["L’homme au repos","Assis contre le mur, gobelet en main."],["La fenêtre à plombs","Une fenêtre à losanges, d’où vient la lumière."]]},"lenain":{"title":"Les joueurs de dés","artist":"Suiveur de Mathieu Le Nain","date":"1630–1680","place":"France","game":"Dés","medium":"Huile sur toile","size":"92,8 × 119,7 cm","credit":"","p":["Œuvre d’un suiveur de Mathieu, le cadet des frères Le Nain. Le musée signale qu’une esquisse d’une composition semblable, par Gabriel de Saint-Aubin, est conservée à la Bibliothèque nationale à Paris.","Trois hommes entourent une petite table ronde en plein air et jettent les dés ; deux autres regardent, celui de gauche serrant une bouteille. À droite, deux lévriers élancés ; au-delà, un vaste paysage. Les petites taches blanches sur la table sont les dés."],"spots":[["Les dés","Des dés sur la table ronde."],["L’homme au chapeau clair","Assis, il tend la main vers le coup."],["L’homme en noir","Un jeune homme debout, poing sur la hanche."],["Le garçon derrière","Il suit la partie derrière la table."],["L’homme à la bouteille","À gauche, il nous sourit."],["Les deux lévriers","Des chiens élancés à droite."]]},"tunisie":{"title":"Partie de cartes devant un café arabe (section tunisienne, Exposition d’Anvers)","artist":"Anonyme (impr. Ch. Bernhoeft)","date":"1894","place":"Belgique (Anvers)","game":"Cartes","medium":"Phototypie","size":"15,4 × 21,6 cm","credit":"","p":["Planche d’une série de 49 sur l’Exposition universelle d’Anvers de 1894, portant « EXPOSITION UNIVERSELLE D’ANVERS 1894 » en haut et « Tunisie. Partie de cartes devant un café arabe » en bas. Elle fut imprimée par Bernhoeft, photographe de la Cour à Luxembourg.","La vue est prise sur une place à coupoles et minaret, bâtie pour la section tunisienne de l’exposition. Des hommes en costume tunisien jouent aux cartes autour de petites tables carrelées ; l’un fume le narguilé, et un plateau de tasses est posé près d’eux. À droite, des visiteurs en costume : sans doute une mise en scène de la vie d’un pays lointain."],"spots":[["La table de jeu","Des hommes, cartes en main, autour d’une table carrelée."],["Le narguilé","Le tuyau du narguilé de l’homme de gauche."],["Les visiteurs","Des hommes en costume assis à droite, sans doute des visiteurs."],["Le plateau de tasses","De petites tasses sous la table."],["Coupoles et minaret","Les bâtiments de style tunisien construits pour l’exposition."],["La légende","« TUNISIE » et « PARTIE DE CARTES DEVANT UN CAFÉ ARABE »."]]},"laghouat":{"title":"Caïds des environs de Laghouat","artist":"Anonyme","date":"1880–1890","place":"Algérie (environs de Laghouat)","game":"Sans doute les dominos","medium":"Tirage sur papier albuminé","size":"20,9 × 27,0 cm","credit":"","p":["Une photographie intitulée « Types algériens. Caïds des environs de Laghouat », collée dans un album et portant le numéro « 239 ». Le caïd était un chef local dans l’Algérie sous domination française.","Des hommes en burnous blancs, assis sur une natte devant un mur de terre, alignent de longues pièces sur une table basse. À leur disposition, il s’agit sans doute de dominos, même si la notice du musée dit seulement « un jeu ». Devant, un plateau à thé et les babouches retirées."],"spots":[["Les pièces sur la table basse","De longues pièces alignées sur la table."],["Le plateau à thé","Verres et théière sur un plateau, devant."],["Les babouches","Les chaussures laissées près de la natte."],["La silhouette debout","Quelqu’un debout près du mur, qui regarde."],["Le mur de terre","Le mur de terre rugueux à l’arrière."],["La natte","La natte tressée où ils sont assis."]]},"hangong":{"title":"Dames du palais (Matin de printemps au palais des Han), détail","artist":"Copie d’après Qiu Ying","date":"Dynastie Qing (1644–1911)","place":"Chine","game":"Weiqi (go)","medium":"Rouleau horizontal ; encre et couleurs sur soie","size":"36,2 × 454,4 cm (rouleau entier)","credit":"","p":["Un détail d’un rouleau horizontal de plus de quatre mètres et demi, copie d’époque Qing d’une composition du peintre Ming Qiu Ying (1494–1552). Dans un palais, un jour de printemps, dames, jeunes filles et servantes se balancent, jouent, admirent les pivoines, font de la musique, jouent du qin, nourrissent un perroquet et des poissons.","Dans cette scène, deux femmes se font face devant un goban derrière une balustrade, et d’autres se penchent pour regarder. Devant, une pierre de lettré dans une vasque en forme de lotus ; des servantes portent instruments et paquets. Comme le note le musée, le rouleau idéalise la vie des femmes dans les appartements intérieurs."],"spots":[["Le goban","Un goban sur une table derrière la balustrade."],["La joueuse qui pose une pierre","Une femme en mauve tendant la main vers le jeu."],["Les spectatrices","Des femmes penchées sur la partie."],["La dame à l’éventail","Une femme tenant un éventail rond entre les piliers."],["La pierre de lettré","Un rocher bleu dans une vasque en lotus."],["La servante à l’instrument","Une servante portant ce qui est sans doute un pipa."]]},"homerbg":{"title":"Backgammon","artist":"Winslow Homer","date":"v. 1877","place":"États-Unis","game":"Backgammon","medium":"Gravure sur bois de bout","size":"","credit":"","p":["Une gravure sur bois d’après un dessin du peintre américain Winslow Homer (1836–1910), qui dessina dans sa jeunesse de nombreuses illustrations pour ce genre d’estampes. En bas est imprimé « 396.—BACKGAMMON.—WINSLOW HOMER. » : sans doute une planche numérotée d’un livre ou d’une revue.","Deux femmes assises face à face sur un canapé orné jouent au backgammon sur un tablier posé en travers de leurs genoux. Un objet rond et blanc repose sur le jeu, sans qu’on sache ce que c’est. Les plis des longues jupes et les accoudoirs en volute sont taillés en traits fins."],"spots":[["Le tablier","Le jeu posé sur les genoux des deux femmes."],["La femme de gauche","Cheveux relevés, elle tend la main vers le jeu."],["La femme de droite","Penchée pour étudier la partie."],["L’accoudoir","Un accoudoir en volute."],["Les jupes","De longues jupes aux plis finement taillés."],["La légende","« 396.—BACKGAMMON.—WINSLOW HOMER. » en bas."]]},"chessst":{"title":"Homme et femme jouant aux échecs (vue stéréoscopique)","artist":"Anonyme","date":"1852–1858","place":"Inconnu","game":"Échecs","medium":"Vue stéréoscopique coloriée","size":"8,3 × 16,5 cm","credit":"","p":["Une paire de photographies montées en vue stéréoscopique, connue en anglais sous le titre « The Chess Players ». Au stéréoscope, l’échiquier et les pièces semblent sortir en relief. La couleur a été ajoutée sur l’image en noir et blanc, au rideau rouge et à la robe jaune.","La femme en jaune a la main sur une pièce, tandis que l’homme en face, vu de dos, étudie la position. Pièces rouges et blanches sont en pleine partie, mais la scène a sans doute été arrangée en atelier. Ces vues de scènes domestiques se vendaient en masse au milieu du XIXe siècle."],"spots":[["L’échiquier","Pièces rouges et blanches sur l’échiquier."],["La main qui joue","La main de la femme sur une pièce."],["La femme","En robe jaune à col blanc, penchée sur le jeu."],["L’homme","Assis de dos."],["Le rideau rouge","Le rideau colorié du fond."],["La seconde image","La vue de droite ; au stéréoscope, la paire prend du relief."]]},"corrida":{"title":"Jeu de dés de la corrida (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"Mexique","game":"Jeu de parcours à deux dés, avec mises","medium":"Similigravure en relief sur papier vélin","size":"40,4 × 30,0 cm","credit":"","p":["Un jeu de parcours illustré par Posada, intitulé « CORRIDA DE TOROS ». Les cases s’enroulent en spirale et montrent dans l’ordre les passes et les moments de la corrida, de la case 1 à l’extérieur jusqu’au centre. Au milieu, des arènes ; en bas, le nom de l’imprimerie d’Antonio Vanegas Arroyo.","Selon l’« Explication » du bas, deux joueurs ou plus misent chacun puis avancent en lançant deux dés. Le 5, « saut à la perche », mène au 10 ; le 12, « coup de corne au picador », fait payer et passer son tour ; le 28, « passe de poitrine », renvoie au départ. Qui atteint le 32, « l’arrastre du taureau », rafle toutes les mises."],"spots":[["Le titre","Les mots « CORRIDA DE TOROS »."],["Les arènes","Le bâtiment des arènes au cœur de la spirale."],["La case 1","Le départ, à l’entrée de la spirale."],["La tête de taureau","Une tête de taureau cornue en haut à droite."],["Le torero","Le portrait d’un torero en bas à gauche."],["L’explication","L’« EXPLICACION » imprimée en pied."]]},"ambrocards":{"title":"Trois hommes jouant aux cartes","artist":"Auteur inconnu (américain)","date":"1865","place":"États-Unis","game":"Cartes","medium":"Ambrotype","size":"14,0 × 11,0 cm","credit":"","p":["L’ambrotype est un négatif léger sur verre, doublé de noir pour paraître positif. Moins cher que le daguerréotype, il fut très répandu en Amérique dans les années 1850–60. Celui-ci se trouve derrière un passe-partout doré, dans un étui tapissé de velours rouge.","Devant un fond uni, trois hommes entourent une petite table, leurs cartes en main. Celui de gauche porte un melon, celui de droite une casquette, tous deux le cigare aux lèvres ; celui du centre, en veste sombre, nous regarde. Ils ont sans doute posé comme en pleine partie pour l’appareil."],"spots":[["Les mains","Des mains tenant les cartes au-dessus de la table."],["L’homme au melon","À gauche, cigare aux lèvres."],["L’homme du centre","En veste sombre, il nous regarde."],["L’homme à la casquette","À droite, cigare aux lèvres."],["Le passe-partout doré","Le cadre doré estampé autour de l’image."],["L’étui","L’étui tapissé de velours rouge."]]},"morphy":{"title":"Paul Morphy, le champion d’échecs","artist":"Winslow Homer","date":"1859","place":"États-Unis","game":"Échecs","medium":"Gravure sur bois de bout","size":"","credit":"","p":["Un portrait gravé sur bois portant « PAUL MORPHY, THE CHESS CHAMPION », d’après un dessin de Winslow Homer (1836–1910), alors jeune illustrateur. Morphy (1837–1884), de La Nouvelle-Orléans, parcourut l’Europe en 1858–59 en battant un maître après l’autre, et rentra célèbre.","Le jeune Morphy, assis, pose la main gauche au bord d’un échiquier, près d’un roi, d’une tour, de pions et d’autres pièces. Fait en 1859, à son retour triomphal, il fut sans doute imprimé comme illustration dans un journal ou une revue."],"spots":[["Les pièces","Un roi, une tour, des pions et d’autres sur l’échiquier."],["La main sur l’échiquier","Sa main gauche au bord du plateau."],["Le visage de Morphy","Le champion, à peine vingt ans passés."],["Le nœud papillon","Un col soigné."],["La main sur le genou","Sa main droite posée sur le genou."],["Le titre","« PAUL MORPHY, THE CHESS CHAMPION » en bas."]]},"dutton":{"title":"La famille Dutton dans le salon de Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"v. 1772","place":"Angleterre","game":"Cartes","medium":"Huile sur toile","size":"101,5 × 127,0 cm","credit":"","p":["Œuvre de Johann Zoffany (1733–1810), peintre né en Allemagne qui fit carrière en Angleterre. La « conversation piece », portrait de famille informel, naquit dans l’Angleterre du XVIIIe siècle et connut une grande vogue. La scène se passe dans le salon de Sherborne Park, dans le Gloucestershire.","Selon le musée, le père et la fille, la mère et le fils réfléchissent au prochain coup d’une partie de cartes. La famille venait de perdre un proche : les parents portent le grand deuil en noir, les enfants le demi-deuil en mauve, blanc et gris."],"spots":[["La table de jeu","Une table au tapis vert et des cartes."],["Le père","En noir, ses cartes en main."],["La fille","En blanc, regardant son jeu."],["Le fils","En gris, ses cartes en main."],["La mère","En grand deuil noir."],["La cheminée","Une cheminée de marbre où brûle un feu."]]},"whist":{"title":"Les universitaires de Noël : partie combinée de whist","artist":"James Bretherton (probablement d’après H. W. Bunbury)","date":"1773","place":"Angleterre","game":"Whist (cartes)","medium":"Eau-forte","size":"26,5 × 39,6 cm","credit":"","p":["Selon le musée, une satire des universitaires de Cambridge. En bas à gauche on semble lire « H. W. Bunbury del. 1772 » et à droite « J. Bretherton f. » ; la feuille fut publiée en 1773 par une boutique de New Bond Street, à Londres. Des bonnets carrés pendent au mur.","Quatre messieurs jouent au whist en se faisant des grimaces. Le whist se joue à deux équipes de deux : la « partie combinée » du titre est sans doute un jeu de mots. Derrière, un homme fait des cornes avec ses doigts au-dessus de la tête d’un autre. Deux serviteurs et deux chiens sont là."],"spots":[["Les cartes","Des cartes jouées sur la table."],["L’universitaire à perruque","Un savant en grande perruque, son jeu contre lui."],["Le geste des doigts","Un homme derrière lève les doigts au-dessus d’une tête."],["La servante","Une domestique en chapeau, un plateau à la main."],["Les bonnets carrés","Des bonnets d’université au mur."],["Le chien de droite","Un petit chien qui aboie en bas à droite."]]},"hey":{"title":"Trois hommes jouant aux échecs","artist":"Paul Hey","date":"1877–1952","place":"Allemagne","game":"Échecs","medium":"Estampe (sans doute eau-forte)","size":"19,3 × 26,0 cm","credit":"","p":["Une estampe du peintre et illustrateur allemand Paul Hey (1867–1952). Trois hommes âgés se penchent sur un même échiquier ; de fines lignes superposées dessinent leurs rides et leurs barbes blanches.","Comme l’indique la notice du musée, l’homme de gauche a la main au menton, et celui de droite tient un cigare en tendant la main vers les pièces. À gauche de la table, deux tasses de café, un verre et une boîte d’allumettes. Sans doute une partie au café."],"spots":[["L’échiquier","Échiquier et pièces sur la table."],["L’homme main au menton","Barbe blanche, plongé dans ses pensées."],["L’homme du milieu","Penché, il tend la main vers une pièce."],["L’homme de droite","Il regarde par-derrière."],["La main au cigare","Un cigare entre les doigts."],["Café et allumettes","Deux tasses, un verre et une boîte d’allumettes à gauche."]]},"artful":{"title":"La carte rusée, ou une de trop pour grand-mère. Cœur est atout !","artist":"Anonyme","date":"1852–1863","place":"Sans doute Grande-Bretagne","game":"Cartes","medium":"Vue stéréoscopique coloriée","size":"8,4 × 17,4 cm","credit":"","p":["Le titre anglais est « The artful card, or, one too many for granny. Hearts are trumps! ». Une petite scène comique où l’on roule grand-mère avec une carte rusée, montée en paire de photographies stéréoscopiques. D’après le titre anglais, elle a sans doute été faite en Grande-Bretagne.","À une table ronde, la grand-mère et une fillette jouent aux cartes, tandis que la jeune femme en vert, son jeu en main, est enlacée par un jeune homme derrière elle. « Cœur est atout » joue sans doute sur la couleur et sur l’amour. La pièce au rouet et au vaisselier est sûrement un décor d’atelier."],"spots":[["Le jeu de la jeune femme","Les cartes que tient la jeune femme en vert."],["Le jeune homme","La main sur son épaule, derrière elle."],["La grand-mère","Une vieille femme en fichu, les yeux sur ses cartes."],["La fillette","Elle sourit en jouant une carte."],["La table","Une table ronde avec cartes et menus objets."],["Le vaisselier","Un meuble vitré garni de vaisselle."]]}};
